<div class="reseller-shell reseller-portal"><div class="container"><div class="reseller-page-toolbar"><div><span class="reseller-kicker">Penjualan Anda</span><h1>Daftar nota</h1><p>Simpan harga jual dan riwayat penawaran customer.</p></div><a href="<?= base_url('reseller/quotes/create') ?>" class="btn-reseller-primary"><i class="fas fa-plus"></i> Nota Baru</a></div><?php if ($success = session()->getFlashdata('success')): ?><div class="reseller-alert success"><p><?= esc($success) ?></p></div><?php endif; ?><section class="reseller-table-card"><?php if ($quotes): ?><div class="table-responsive"><table class="reseller-table"><thead><tr><th>Nomor Nota</th><th>Customer</th><th>Tanggal</th><th>Total Jual</th><th>Margin</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($quotes as $quote): ?><tr><td><strong><?= esc($quote['quote_number']) ?></strong></td><td><?= esc($quote['customer_name']) ?></td><td><?= date('d M Y', strtotime($quote['created_at'])) ?></td><td>Rp <?= number_format($quote['selling_total'], 0, ',', '.') ?></td><td class="reseller-private">Rp <?= number_format($quote['selling_total'] - $quote['base_total'], 0, ',', '.') ?></td><td><span class="quote-status <?= esc($quote['status']) ?>"><?= esc(ucfirst($quote['status'])) ?></span></td><td><a href="<?= base_url('reseller/quotes/' . $quote['id']) ?>">Detail</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="reseller-empty"><i class="fas fa-file-circle-plus"></i><h2>Belum ada nota</h2><p>Mulai dengan memilih produk dan menentukan harga jual Anda.</p></div><?php endif; ?></section></div></div>
